"""
Computes the largest generalized eigenvalue lambda solving det(X - lambda*Y) = 0 for two real symmetric positive definite (32,32) matrices X and Y, via a Cholesky congruence transform reducing the problem to an ordinary symmetric eigenvalue problem.

Given two real symmetric positive definite $32\times 32$ matrices $X$ and $Y$, computes the largest generalized eigenvalue $\lambda$ solving $\det(X - \lambda Y) = 0$, via a Cholesky congruence transform: writing $Y = LL^{T}$, the generalized eigenvalue problem reduces to the ordinary symmetric eigenvalue problem for $L^{-1} X L^{-T}$, whose largest eigenvalue is $\lambda_{\max}(X, Y)$.










Formulas:










$Y = LL^{T}$ (Cholesky factorization)










$Z = L^{-1} X L^{-T}$










$\lambda_{\max}(X, Y)$ = largest eigenvalue of $Z$

Returns
-------
lam_max : float, the largest generalized eigenvalue of the pencil (X, Y).
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

import numpy as np
from scipy.linalg import cholesky, solve_triangular


def generalized_eigenvalue_definite_pencil(X: np.ndarray, Y: np.ndarray) -> float:
    """Compute the largest generalized eigenvalue lambda solving
    det(X - lambda*Y) = 0, for X, Y real symmetric positive definite.

    Parameters
    ----------
    X : np.ndarray
        (32, 32) real symmetric positive definite matrix.
    Y : np.ndarray
        (32, 32) real symmetric positive definite matrix.

    Returns
    -------
    lam_max : float
        The largest generalized eigenvalue of the pencil (X, Y).

    Raises
    ------
    ValueError
        If X or Y does not have shape (32, 32), or if Y is not symmetric
        positive definite.
    """
    lam_max = 0.0  # placeholder
    return lam_max

# =============================================================================
# GOLD SOLUTION
# =============================================================================

import numpy as np
from scipy.linalg import cholesky, solve_triangular


def _oracle_generalized_eigenvalue_definite_pencil(X: np.ndarray, Y: np.ndarray) -> float:
    X = np.asarray(X, dtype=float)
    Y = np.asarray(Y, dtype=float)
    if X.shape != (32, 32) or Y.shape != (32, 32):
        raise ValueError("X and Y must have shape (32,32)")
    if not np.allclose(Y, Y.T, atol=1e-8):
        raise ValueError("Y must be symmetric")
    try:
        L = cholesky(Y, lower=True)
    except np.linalg.LinAlgError:
        raise ValueError("Y must be positive definite")
    W = solve_triangular(L, X, lower=True)
    Z = solve_triangular(L, W.T, lower=True).T
    Z = 0.5 * (Z + Z.T)
    lam_max = float(np.linalg.eigvalsh(Z).max())
    return lam_max

